# Conectar
mysql -u root

# Comandos en mysql CLI
SHOW DATABASES;
USE nombre_db;
SHOW TABLES;
DESCRIBE nombre_tabla;

# Ver usuarios
SELECT user, host FROM mysql.user;

-- Crear usuario con permisos específicos
CREATE USER 'miapp'@'localhost' IDENTIFIED BY 'ContraseñaSegura123';
CREATE USER 'miapp'@'%' IDENTIFIED BY 'ContraseñaSegura123';

-- Dar permisos sobre una base de datos
GRANT ALL PRIVILEGES ON mitienda.* TO 'miapp'@'localhost';
GRANT ALL PRIVILEGES ON mitienda.* TO 'miapp'@'%';

-- Dar permisos de solo lectura
GRANT SELECT ON mitienda.* TO 'lector'@'localhost' IDENTIFIED BY 'lectorpass';

-- Aplicar cambios
FLUSH PRIVILEGES;

-- Revocar permisos
REVOKE DELETE ON mitienda.* FROM 'miapp'@'localhost';

-- Eliminar usuario
DROP USER 'miapp'@'localhost';

-- Insertar
INSERT INTO productos (nombre, precio, stock) VALUES ('Tablet', 399.99, 20);
INSERT INTO productos (nombre, precio, stock) VALUES
    ('Monitor 27"', 249.00, 12),
    ('Ratón Inalámbrico', 29.99, 55);

-- Leer
SELECT * FROM productos WHERE stock > 0 ORDER BY precio;
SELECT nombre, precio FROM productos WHERE categoria = 'Electrónica';

-- Actualizar
UPDATE productos SET stock = stock - 1 WHERE id = 3;
UPDATE productos SET precio = precio * 0.9 WHERE stock > 50;

-- Eliminar
DELETE FROM productos WHERE id = 10;
DELETE FROM productos WHERE stock = 0 AND precio < 10;
